Här är en funktion som upptäcker två vanliga intrångsmönster: **portskanning** (många unika portar från samma IP) och **brute force** (många misslyckade försök från samma IP).

```python
from collections import defaultdict

def detect_intrusion(packet_log: list[dict]) -> list[dict]:
    """Identifierar misstänkta intrångsförsök i nätverksloggar.

    Varje paket förväntas ha nycklarna: src_ip, dst_port, status.
    Returnerar en lista med larm för misstänkta IP-adresser.
    """
    PORT_SCAN_THRESHOLD = 10   # unika portar från samma IP
    BRUTE_FORCE_THRESHOLD = 5  # misslyckade försök från samma IP

    ports_per_ip = defaultdict(set)
    failed_per_ip = defaultdict(int)

    for packet in packet_log:
        src = packet.get("src_ip")
        if not src:
            continue
        ports_per_ip[src].add(packet.get("dst_port"))
        if packet.get("status") == "failed":
            failed_per_ip[src] += 1

    alerts = []
    for ip, ports in ports_per_ip.items():
        if len(ports) >= PORT_SCAN_THRESHOLD:
            alerts.append({
                "src_ip": ip,
                "type": "port_scan",
                "details": f"{len(ports)} unika portar skannade",
            })
    for ip, fails in failed_per_ip.items():
        if fails >= BRUTE_FORCE_THRESHOLD:
            alerts.append({
                "src_ip": ip,
                "type": "brute_force",
                "details": f"{fails} misslyckade försök",
            })
    return alerts
```

