import os
import stat


def audit_file_permissions(directory: str) -> list[dict]:
    """Granskar filrättigheter och identifierar filer med för generösa behörigheter."""
    findings = []

    for root, _, files in os.walk(directory):
        for name in files:
            path = os.path.join(root, name)
            try:
                mode = os.stat(path).st_mode
            except OSError:
                continue  # Hoppa över filer som inte kan läsas

            issues = []
            if mode & stat.S_IWOTH:
                issues.append("world-writable")
            if mode & stat.S_IWGRP:
                issues.append("group-writable")
            if mode & stat.S_ISUID:
                issues.append("setuid")
            if mode & stat.S_ISGID:
                issues.append("setgid")

            if issues:
                findings.append({
                    "path": path,
                    "permissions": oct(stat.S_IMODE(mode)),
                    "issues": issues,
                })

    return findings
```

