import os
import stat

def find_writable_files(directory: str) -> list[str]:
    """Hittar world-writable filer – en klassisk felkonfiguration som kan
    utnyttjas för privilege escalation (t.ex. skript som körs av root)."""
    writable = []
    for root, _, files in os.walk(directory):
        for name in files:
            path = os.path.join(root, name)
            try:
                mode = os.lstat(path).st_mode
                if stat.S_ISREG(mode) and mode & stat.S_IWOTH:
                    writable.append(path)
            except OSError:
                continue
    return writable
```

